package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Validates a new owner before {@link BuildOwner} runs: every one of firstName, lastName, address,
 * city and telephone must be present and non-blank. Any that are missing or blank are collected and
 * reported together as a {@link MissingOwnerFieldsException} (a 400), so the body is never persisted.
 *
 * <p>The telephone is then normalized to E.164 (keep a leading '+' and country code when present,
 * otherwise assume '+61' and drop a single leading '0' from the national digits, stripping spaces,
 * dashes and brackets and requiring 8 to 15 digits after the '+'); otherwise an
 * {@link InvalidTelephoneException} (a 400) is raised. The E.164 value is written back onto the request
 * so downstream steps store and return it.
 *
 * <p>Deliberately does <em>not</em> use {@code @Valid}: bean validation would raise a
 * {@code MethodArgumentNotValidException} with a different response shape, whereas this rule must
 * answer with an {@code errors} array naming each offending field.
 */
public class ValidateNewOwner {

    /**
     * Syntactic email check (the HTML5/Hibernate-Validator {@code @Email} form): a local part of the
     * permitted characters, an {@code @}, then a dot-separated domain of label segments. Used only to
     * decide between accept and 400; a valid value is then lower-cased and written back onto the request.
     */
    private static final Pattern EMAIL_PATTERN = Pattern.compile(
            "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
                    + "(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
        // This list mirrors OwnerFieldsDto's required fields by hand: it must track the schema's
        // `required` set. We check presence/non-blankness only, a narrower rule than the DTO's full
        // constraints (@Size/@Pattern), so bean validation is intentionally not used here.
        // Normalize the address first so the required-field check rejects an address that is blank
        // after normalization (e.g. "   "), and so downstream steps store/return and compare the
        // canonical form. OwnerAddress.normalize yields "" for a null or all-whitespace address.
        String normalizedAddress = OwnerAddress.normalize(request.getAddress());
        request.setAddress(normalizedAddress);

        List<String> missing = new ArrayList<>();
        require(missing, "firstName", request.getFirstName());
        require(missing, "lastName", request.getLastName());
        require(missing, "address", normalizedAddress);
        require(missing, "city", request.getCity());
        require(missing, "telephone", request.getTelephone());
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }

        // Normalize the telephone to E.164. Store the canonical value back so BuildOwner/SaveOwner
        // persist it and the response echoes the E.164 form.
        String e164 = OwnerTelephone.toE164(request.getTelephone());
        if (e164 == null) {
            throw new InvalidTelephoneException(request.getTelephone());
        }
        request.setTelephone(e164);

        // Email is optional: only an email that is present (non-blank) must be a valid address. A valid
        // value is lower-cased and written back (like telephone above) so downstream steps store and
        // return the canonical form.
        String email = request.getEmail();
        if (email != null && !email.isBlank()) {
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                throw new InvalidEmailException(email);
            }
            request.setEmail(email.toLowerCase());
        }

        validated.set(request);
    }

    private static void require(List<String> missing, String field, String value) {
        if (value == null || value.isBlank()) {
            missing.add(field);
        }
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date (supplied in the request, or the server date when omitted)
        // must fall on a business day: a weekend date rolls forward to the next Monday. Every value
        // derived from it (membership number year, daily-limit bucket) then uses this adjusted date.
        owner.setRegistrationDate(RegistrationDates.effective(owner.getRegistrationDate()));
        built.set(owner);
    }
}
===== ValidateOwnerPostcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates an owner's postcode when one is supplied, so an unacceptable value is a 400 before the
 * owner is ever persisted. Runs after the body has been bound and published (by {@link ValidateNewOwner}
 * on create / {@link ValidateOwner} on update) and before the owner is built or loaded.
 *
 * <p>Postcode is optional: a {@code null} or blank value is left untouched and accepted. When present it
 * must be exactly four digits; otherwise it is rejected. The city's region is derived through the single
 * {@link Owner#regionOf(String) city-to-region table}, and when the region is known the postcode must
 * fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
 * no known region accepts any four-digit postcode.
 */
public class ValidateOwnerPostcode {

    /** A postcode is exactly four digits. */
    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent — request contract stays backward-compatible
        }
        if (!POSTCODE.matcher(postcode).matches()) {
            throw new InvalidPostcodeException(postcode, "must be four digits");
        }
        int[] range = Owner.postcodeRangeOf(Owner.regionOf(request.getCity()));
        if (range != null) {
            int value = Integer.parseInt(postcode);
            if (value < range[0] || value > range[1]) {
                throw new InvalidPostcodeException(postcode,
                        "out of range " + range[0] + "-" + range[1] + " for city '" + request.getCity() + "'");
            }
        }
    }
}

