package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags this owner as a <em>possible</em> (soft) duplicate. An owner is a possible duplicate when some
 * other owner shares its last name (compared case-insensitively) and postcode but has a different
 * telephone — a near match that is not a hard duplicate (a hard duplicate shares the whole identity key,
 * including the telephone, and is rejected earlier by {@link CheckIdentityUnique}).
 *
 * <p>Sets {@code possibleDuplicate} to {@code true} and {@code possibleDuplicateOf} to the matching
 * owner's id (the earliest match when several match); otherwise {@code possibleDuplicate} is {@code false}
 * and {@code possibleDuplicateOf} is {@code null}. Both are computed per request, not persisted, so the
 * flag is recomputed identically on each read. The owner itself is excluded from the comparison by id.
 */
public class FlagPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setPossibleDuplicate(false);
        owner.setPossibleDuplicateOf(null);

        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        String telephone = owner.getTelephone();
        if (postcode == null || postcode.isBlank()) {
            return;
        }

        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (isSelf(owner, existing)) {
                continue;
            }
            if (!equalsIgnoreCase(lastName, existing.getLastName())) {
                continue;
            }
            if (!postcode.equals(existing.getPostcode())) {
                continue;
            }
            if (equals(telephone, existing.getTelephone())) {
                continue; // same telephone would be a hard duplicate, not a possible one
            }
            if (match == null || isEarlier(existing, match)) {
                match = existing;
            }
        }

        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
    }

    private static boolean isSelf(Owner owner, Owner existing) {
        return owner.getId() != null && owner.getId().equals(existing.getId());
    }

    private static boolean isEarlier(Owner candidate, Owner current) {
        Integer a = candidate.getId();
        Integer b = current.getId();
        if (a == null) {
            return false;
        }
        if (b == null) {
            return true;
        }
        return a < b;
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }

    private static boolean equals(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a new owner whose city already contains {@link #CAPACITY} or more owners, so the request is
 * answered with a 409 Conflict rather than exceeding the per-city capacity. Cities are compared in
 * their {@link OwnerCity#normalize normalized} form (whitespace collapsed, lower-cased), consistent
 * with the other create-time checks. Runs after {@link CheckIdentityUnique} and before
 * {@link BuildOwner}.
 */
public class CheckCityCapacity {

    /** Maximum number of owners permitted per city. */
    static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        String normalizedCity = OwnerCity.normalize(city);
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (normalizedCity.equals(OwnerCity.normalize(existing.getCity()))) {
                count++;
            }
        }
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city, CAPACITY);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Single source of truth for what a "normalized" owner telephone is: the E.164 form. Both
 * {@link ValidateNewOwner} (which enforces the rule and stores the E.164 value) and
 * {@link OwnerIdentity} (whose identity key compares against stored owners) normalize through here, so
 * the two cannot drift apart.
 *
 * <p>Normalization strips spaces, dashes and brackets, then forms the canonical E.164 string:
 * <ul>
 *   <li>a leading {@code '+'} and country code are kept as-is;</li>
 *   <li>otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
 *       the national digits.</li>
 * </ul>
 * The result must be a {@code '+'} followed by 8 to 15 digits. On top of that general rule, the
 * national-number length (the digits after the country code) must match the country code when it is one
 * we recognize: {@code +61} requires 9 national digits and {@code +1} requires 10 (see
 * {@link #NATIONAL_LENGTHS}). Anything else — non-digit leftovers, a total digit count outside 8 to 15,
 * or a national-number length that is wrong for a recognized country code — is not valid E.164 and
 * yields {@code null}. A country code that is not in the table is accepted on the general rule alone.
 */
final class OwnerTelephone {

    /** A valid E.164 value: '+' then 8 to 15 digits. */
    private static final Pattern E164 = Pattern.compile("^\\+[0-9]{8,15}$");

    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");

    /**
     * Country code (without the '+') to its required national-number length. Iterated longest-code-first
     * (hence {@link LinkedHashMap}) so a longer code is matched before a shorter one that is a prefix of
     * the number. Country codes absent here are not length-checked.
     */
    private static final Map<String, Integer> NATIONAL_LENGTHS;
    static {
        Map<String, Integer> lengths = new LinkedHashMap<>();
        lengths.put("61", 9); // Australia
        lengths.put("1", 10); // North American Numbering Plan
        NATIONAL_LENGTHS = lengths;
    }

    private OwnerTelephone() {
    }

    /**
     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form valid E.164.
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
        String digits;
        if (cleaned.startsWith("+")) {
            // Keep the explicit country code; the '+' is re-added below.
            digits = cleaned.substring(1);
        }
        else {
            // No country code: assume +61 and drop a single leading '0' from the national digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        String e164 = "+" + digits;
        if (!E164.matcher(e164).matches()) {
            return null;
        }
        return hasValidNationalLength(digits) ? e164 : null;
    }

    /**
     * Whether the national-number length of {@code digits} (a '+'-less E.164 digit string) matches its
     * country code. Unrecognized country codes pass (checked only by the general 8-to-15 rule above).
     */
    private static boolean hasValidNationalLength(String digits) {
        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
            String code = entry.getKey();
            if (digits.startsWith(code)) {
                return digits.length() - code.length() == entry.getValue();
            }
        }
        return true;
    }
}

